css:
:scope{display:block;width:100%}.pw{--bg:#0F0E0C;--tx:#EDE6D8;--lb:#C2B8A6;--rl:#8E4A30;--hl:#3A3531;background:var(--bg);color:var(--tx);font-family:var(--os-font-body);font-weight:400}.pw[data-ground="bone"]{--bg:#EDE6D8;--tx:#0F0E0C;--lb:#3A3531;--rl:#8E4A30;--hl:#3A3531}.pw[data-ground="umber"]{--bg:#3A3531;--rl:#C2B8A6;--hl:#C2B8A6}.pw[data-ground="oxblood"]{--bg:#4A1C18;--rl:#C2B8A6;--hl:#C2B8A6}.pw[data-ground="clay"]{--bg:#8E4A30;--lb:#EDE6D8;--rl:#EDE6D8;--hl:#EDE6D8}.pw[data-ground="olive"]{--bg:#3C402F;--rl:#C2B8A6;--hl:#C2B8A6}
.pw__in{box-sizing:content-box;max-width:1200px;margin:0 auto;padding:112px 32px}
.pw__kicker{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.3em;text-transform:uppercase;color:var(--lb)}
.pw__rule{width:64px;height:2px;background:var(--rl);margin:28px 0 32px}
.pw__in>.pw__rule:first-child{margin-top:0}
.pw__h2{margin:0;font-family:var(--os-font-heading);font-weight:500;font-size:60px;line-height:1.08;color:var(--tx);text-wrap:balance}
.pw__h2[data-size="large"]{font-size:64px;line-height:1.05}
.pw__fig{margin:28px 0 0;max-width:40em}
.pw__q{margin:0;font-family:var(--os-font-heading);font-style:italic;font-weight:500;font-size:26px;line-height:1.35;color:var(--lb)}
.pw__by{margin-top:14px;font-family:var(--os-font-label);font-size:11px;letter-spacing:.24em;text-transform:uppercase;color:var(--lb)}
.pw__grid{display:grid;gap:40px;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));margin-top:64px}
.pw__card{border-top:1px solid var(--hl);padding-top:24px}
.pw__label{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:13px;letter-spacing:.3em;text-transform:uppercase;color:var(--lb)}
.pw__body{margin:14px 0 0;font-size:21px;line-height:1.5;color:var(--tx)}
.pw__learn{margin-top:64px;display:flex;flex-wrap:wrap;gap:48px}
.pw__ll{flex:1 1 260px}
.pw__list{flex:999 1 560px;margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:16px;font-size:21px;line-height:1.45;color:var(--tx)}
.pw__list li{border-bottom:1px solid var(--hl);padding-bottom:16px}
.pw__note{margin:48px 0 0;font-size:19px;line-height:1.5;color:var(--lb);max-width:36em}
@media (max-width:767px){.pw__in{padding:56px 20px}.pw__kicker{font-size:11px}.pw__rule{width:48px;margin:24px 0}.pw__h2,.pw__h2[data-size="large"]{font-size:40px;line-height:1.1}.pw__q{font-size:22px}.pw__grid{grid-template-columns:1fr;gap:28px;margin-top:36px}.pw__body,.pw__list{font-size:19px}.pw__learn{margin-top:40px;gap:20px}.pw__note{margin-top:32px;font-size:18px}}
